# ELEKTRON — risultati di riferimento dei test del motore (test/engine.test.js).
# Calcolati con le formule chiuse dei libri di testo, senza usare il codice di Elektron: python test/fixtures/riferimento.py
# Risultati di riferimento con formule chiuse (come nei libri di testo), indipendenti dal motore di Elektron.
from math import *
par=lambda *r: 1/sum(1/x for x in r)
out=[]
def p(name, **kv): out.append((name, kv))
# A. grandezze, Ohm, potenza
p('ohm-V', V=4700*0.002)
p('ohm-I', I=12/470)
p('ohm-R', R=230/0.5)
p('pot-VI', P=12*0.5)
p('pot-RI', P=1000*0.01**2)
p('pot-VR', P=9**2/330)
p('pot-Imax', I=sqrt(0.25/1000))
p('energia', Wh=2000*1.5)
p('carica', Q=2*30)
p('resistivita', R=0.0175*100/1.5)
p('tolleranza', min=4700*0.95, max=4700*1.05)
# B. serie e parallelo
p('serie', Req=650, I=12/650, V2=220*12/650)
p('parallelo3', Req=par(100,200,300))
p('parallelo2', Req=par(4700,10000))
p('parallelo-uguali', Req=330/3)
p('mista1', Req=100+par(200,300), I3=12/(100+par(200,300))*200/500)
p('mista2', Req=par(3000,3000), I=9/1500, I3=9/3000)
Rq=1000+par(2000,3000); I=11/Rq; V1=11-1000*I; p('scala', Req=Rq, I=I, V4=V1/3000*2000)
# C. partitori
p('partitore1', V2=12*2/3)
p('partitore2', V2=5*4.7/14.7)
p('partitore-carico1', VL=12*500/1500)
r2l=par(10000,100000); p('partitore-carico2', VL=10*r2l/(10000+r2l))
p('partitore-corrente', I1=0.03*2000/3000, I2=0.03*1000/3000)
# D. Kirchhoff e Millman
p('kcl1', I3=0.002-0.005)
p('kcl2', I=0.010+0.005-0.003)
p('kvl1', V2=12-5)
v=(12/100+6/300)/(1/100+1/200+1/300); p('millman1', VAB=v, I3=v/200, I1=(12-v)/100, I2=(6-v)/300)
v=(12/100+12/300)/(1/100+1/200+1/300); p('millman2', VAB=v)
v=(10/1000+5/2000)/(1/1000+1/1000+1/2000); p('millman3', VAB=v, I3=v/1000, I2=(5-v)/2000)
# E. Thevenin, Norton, potenza massima
p('thevenin1', Vth=8, Rth=par(1000,2000), IN=12/1000)
rth=par(1000,2000)+500; p('thevenin2', Rth=rth, IL=8/(rth+1000), VL=8/(rth+1000)*1000)
p('thevenin3', Vth=24*3/9, Rth=par(6000,3000), IL=8/4000, Pmax=8**2/(4*2000))
p('norton1', IN=8/par(100,400))
p('potenza-massima', Pmax=12**2/(4*50))
p('thevenin-corrente', Vth=0.01*1000, Rth=1000)
# F. sovrapposizione
p('sovrapposizione1', I3a=12/(100+par(200,300))*300/500, I3b=6/(300+par(100,200))*100/300)
p('sovrapposizione2', I3a=10/(1000+par(2000,1000))*2000/3000, I3b=5/(2000+par(1000,1000))*1000/2000)
# G. condensatori e induttori
p('C-parallelo', C=10e-6+22e-6+47e-6)
p('C-serie', C=par(10e-6,22e-6))
p('C-carica', Q=100e-6*12)
p('C-energia', W=0.5*470e-6*25**2)
p('L-tensione', v=10e-3*2/1e-3)
p('L-energia', W=0.5*0.1*0.5**2)
# H. sinusoidi e alternata
p('periodo', T=1/50, w=2*pi*50)
p('efficace', Veff=325/sqrt(2), Vp=230*sqrt(2), Vpp=2*230*sqrt(2))
p('medio', semi=10/pi, doppia=20/pi)
p('XL', X=2*pi*50*0.1)
p('XC', X=1/(2*pi*50*10e-6))
xc=1/(2*pi*1000*100e-9); z=hypot(1000,xc); p('RC-serie', Z=z, phi=degrees(atan2(-xc,1000)), I=10/z)
xl=2*pi*100*0.1; z=hypot(100,xl); p('RL-serie', Z=z, phi=degrees(atan2(xl,100)))
xl=2*pi*100*0.1; xc=1/(2*pi*100*10e-6); x=xl-xc; z=hypot(100,x); i=230/z
p('RLC-serie', X=x, Z=z, I=i, P=100*i*i, Q=abs(x)*i*i, S=230*i, phi=degrees(atan2(x,100)))
f0=1/(2*pi*sqrt(0.01*100e-9)); Qf=2*pi*f0*0.01/10; p('risonanza', f0=f0, Q=Qf, B=f0/Qf)
p('potenze', P=230*5*cos(radians(30)), Q=230*5*sin(radians(30)), S=1150)
t1=tan(acos(0.7)); t2=tan(acos(0.95)); qc=1000*(t1-t2); p('rifasamento', Qc=qc, C=qc/(2*pi*50*230**2))
p('sfasamento', phi=360*2/20)
iR=10/100; iL=10/(2*pi*100*0.1); iC=10*2*pi*100*10e-6; p('RLC-parallelo', I=hypot(iR, iC-iL))
p('passa-basso-fc', mod=1/sqrt(2), phi=-45.0)
p('passa-alto-fc', mod=1/sqrt(2), phi=45.0)
# J. semiconduttori (modelli dichiarati: soglia 0,7 V; VBE 0,7 V; VCEsat 0,2 V)
p('diodo-soglia', I=(5-0.7)/1000, Iid=5/1000)
p('led', I=(9-2)/330)
p('diodi-serie', I=(12-1.4)/1000)
p('zener1', VL=5.1, IR=(12-5.1)/470, IL=5.1/1000, IZ=(12-5.1)/470-5.1/1000)
p('zener2', VL=12*200/670)
p('bjt-sat', IB=(5-0.7)/10000, IC=(12-0.2)/1000, VCE=0.2)
ib=(5-0.7)/470000; p('bjt-att', IB=ib, IC=100*ib, VCE=12-1000*100*ib)
vth=12*10/57; rth=par(47000,10000); ib=(vth-0.7)/(rth+101*1000); p('bjt-partitore', IB=ib, IC=100*ib, VCE=12-2200*100*ib-1000*101*ib)
p('mosfet', ID=12/100.1)
# K. operazionale ideale
p('invertente', Vo=-0.5*10)
p('invertente-sat', Vo=-12)
p('non-invertente', Vo=1*(1+4.7))
p('inseguitore', Vo=3.3)
p('sommatore', Vo=-(20/10*1+20/10*0.5))
p('differenziale', Vo=20/10*(1.5-1))
p('comparatore', Vo1=12, Vo2=-12)
import json
print(len(out))
for n,kv in out: print(n, json.dumps({k: float('%.10g'%v) for k,v in kv.items()}))

# ---- Tappa 2: transitori, dispositivi, segnali (test/engine2.test.js) ----
from math import *
import json
out2=[]
def p(n, **kv): out2.append((n, kv))
# transitori
p('tau-RC', tau=10000*100e-6)
p('tau-RL', tau=0.1/50)
p('carica-1tau', v=12*(1-exp(-1)))
p('carica-t', v=10*(1-exp(-0.5/1.0)))
p('scarica-t', v=12*exp(-2e-3/1e-3))
p('carica-tempo', t=-1e-3*log(1-6/10))
p('scarica-corrente', i=-12/1000*exp(-1))
p('RL-corrente', i=12/100*(1-exp(-1e-3/1e-3)))
p('cinque-tau', t=5*4.7e3*10e-6)
# dispositivi
p('led-R', R=(5-2)/0.015, Rc=220.0, P=220*((5-2)/220)**2)
p('raddrizzatore-semi', Vp=12*sqrt(2)-0.7, Vmed=(12*sqrt(2)-0.7)/pi)
vp=12*sqrt(2)-1.4; vr=0.5/(100*1000e-6); p('raddrizzatore-ponte', Vp=vp, Vr=vr, Vdc=vp-vr/2)
p('bjt-guadagno', IC=150*20e-6, IE=150*20e-6+20e-6)
vb=12*10/57; ie=(vb-0.7)/1000; p('bjt-partitore-approx', VB=vb, IE=ie, VCE=12-ie*3200)
ics=(12-0.2)/100; p('bjt-interruttore', RB=(5-0.7)/(2*ics/100), RBc=1800.0)
p('mosfet-potenza', P=0.1*(12/100.1)**2)
b=10/(10+47); p('schmitt', VT=12*b, H=2*12*b)
b=0.5; p('astabile-op', T=2*10e3*100e-9*log(3), f=1/(2*10e3*100e-9*log(3)))
th=0.693*11e3*100e-9; tl=0.693*10e3*100e-9; p('ne555-astabile', tH=th, tL=tl, f=1/(th+tl), D=100*th/(th+tl))
p('ne555-mono', T=1.1*100e3*10e-6)
p('wien', f0=1/(2*pi*10e3*10e-9))
p('trasformatore', V2=230*50/1000)
p('lineare', P=(12-5)*0.5, eta=100*5/12)
p('lm317', Vout=1.25*(1+720/240))
p('pt100', R=100*(1+0.00385*50), T=(119.25/100-1)/0.00385)
p('lm35', V=0.01*37, T=0.25/0.01)
p('ntc', R=10000*exp(3950*(1/323.15-1/298.15)))
p('condizionamento', G=5/1.0, Voff=-1.0, Vout=5*0.7-1)
# segnali
p('db', G=20*log10(10), Gp=10*log10(100), A=10**(-3/20))
fc=1/(2*pi*1000*100e-9); p('passa-basso', fc=fc, mod=1/sqrt(1+(10000/fc)**2), dB=20*log10(1/sqrt(1+(10000/fc)**2)), phi=-degrees(atan(10000/fc)))
x=100/fc; p('passa-alto', mod=x/sqrt(1+x*x), phi=90-degrees(atan(x)))
p('bode-asintotico', G=-20*log10(10000/fc))
p('filtro-attivo', K=-10, fc=1/(2*pi*10e3*10e-9))
q=5/1024; p('adc', Q=q, err=q/2, N=round(1.5/q), Vout=512*q)
p('adc8', Q=10/256, N=round(3.3/(10/256)))
p('dac-pesato', Vout=-5*1*(1+0/2+1/4+1/8))
p('campionamento', fs=2*20000, alias=abs(7000-1*6000))
print(len(out2))
for n,kv in out2: print(n, json.dumps({k: float('%.10g'%v) for k,v in kv.items()}))
